import {V,Q,definition,component} from './engine.js';
import {makePart} from './geometry.js';
import {ConvexHull} from './vendor/ConvexHull.js';
import {partMass,localMassCenter} from './mass.js';
import {groundedParts,assertUngrounded} from './grounding.js';
import {transformParts} from './motion.js';
const cache=new Map(),G=9810,H=1/240,CONTACT=.2;
export function hullPoints(points){if(points.length<4)return points;const hull=new ConvexHull().setFromPoints(points),seen=new Set(),result=[];for(const face of hull.faces){let edge=face.edge;do{const p=edge.head().point;if(!seen.has(p)){seen.add(p);result.push(p.clone());}edge=edge.next;}while(edge!==face.edge);}return result.length?result:points;}
export function shapePoints(type,part){if(!part?.path&&!part?.belt&&cache.has(type))return cache.get(type);const g=makePart(type,part),points=[],seen=new Set();g.updateMatrixWorld(true);g.traverse(o=>{const a=o.geometry?.attributes?.position;if(!a)return;for(let i=0;i<a.count;i++){const p=V([a.getX(i),a.getY(i),a.getZ(i)]).applyMatrix4(o.matrixWorld),key=p.toArray().map(v=>v.toFixed(4)).join(',');if(!seen.has(key)){seen.add(key);points.push(p);}}});const hull=hullPoints(points);if(!part?.path&&!part?.belt)cache.set(type,hull);return hull;}
export function worldPoints(model,ids){return model.parts.filter(p=>ids.has(p.id)).flatMap(p=>{const q=Q(p.quat),pos=V(p.pos);return shapePoints(p.type,p).map(v=>v.clone().applyQuaternion(q).add(pos));});}
export function massData(model,ids){let mass=0,overrides=0;const center=V(),particles=[];for(const p of model.parts)if(ids.has(p.id)){const d=definition(p),m=partMass(p,d),pos=V(localMassCenter(p,d)).applyQuaternion(Q(p.quat)).add(V(p.pos));mass+=m;center.addScaledVector(pos,m);overrides+=p.massG!==undefined?1:0;particles.push({id:p.id,m,pos,own:d.group==='rods'?m*d.length*d.length/12:m*(d.motor?28:d.diameter?d.diameter/3:8)**2});}if(!mass)throw Error('Select a build first.');return{mass,center:center.divideScalar(mass),particles,overrides};}
const cross=(a,b,c)=>(b.x-a.x)*(c.z-a.z)-(b.z-a.z)*(c.x-a.x);
export function supportHull(points){const unique=[...new Map(points.map(p=>[p.x.toFixed(4)+','+p.z.toFixed(4),p])).values()].sort((a,b)=>a.x-b.x||a.z-b.z);if(unique.length<=2)return unique.map(p=>p.clone());const half=a=>{const h=[];for(const p of a){while(h.length>1&&cross(h.at(-2),h.at(-1),p)<=1e-8)h.pop();h.push(p);}return h;};return [...half(unique).slice(0,-1),...half([...unique].reverse()).slice(0,-1)].map(p=>p.clone());}
export function supportAnalysis(points,center){const bottom=Math.min(...points.map(p=>p.y)),hull=supportHull(points.filter(p=>p.y<=bottom+CONTACT));let margin=Infinity,edge=null;if(hull.length>=3){for(let i=0;i<hull.length;i++){const a=hull[i],b=hull[(i+1)%hull.length],d=cross(a,b,center)/Math.hypot(b.x-a.x,b.z-a.z);if(d<margin){margin=d;edge=[a,b];}}}else{const a=hull[0],b=hull[1]||a;if(!a)throw Error('No floor contact geometry.');const v=b.clone().sub(a);v.y=0;const t=v.lengthSq()?Math.max(0,Math.min(1,center.clone().sub(a).dot(v)/v.lengthSq())):0,nearest=a.clone().addScaledVector(v,t);margin=-Math.hypot(center.x-nearest.x,center.z-nearest.z);edge=[nearest,nearest];}return {bottom,hull,margin,edge,stable:margin>=-.02&&hull.length>=3};}
export function stabilityReport(model,id){const ids=component(model,id),mass=massData(model,ids),points=worldPoints(model,ids),support=supportAnalysis(points,mass.center),anchors=groundedParts(model,ids);return{ids,...mass,...support,anchors,points,status:anchors.length?'anchored':support.stable?'stable':support.margin>=-.02?'balanced on edge':'unstable'};}
export function placeOnFloor(model,ids){assertUngrounded(model,ids);const points=worldPoints(model,ids),bottom=Math.min(...points.map(p=>p.y));transformParts(model,ids,[0,0,0],[0,1,0],0,[0,-bottom,0]);return -bottom;}
export function createTopple(model,id){const report=stabilityReport(model,id);assertUngrounded(model,report.ids);placeOnFloor(model,report.ids);const mass=massData(model,report.ids);return {ids:report.ids,...mass,points:hullPoints(worldPoints(model,report.ids)),pivot:null,omega:0,accumulator:0,elapsed:0,impacts:0,phase:'resting',angleTravel:0};}
function choosePivot(body,direction=null){const s=supportAnalysis(body.points,body.center);let edge=s.edge;if(direction&&s.hull.length>=3){let best=-Infinity;for(let i=0;i<s.hull.length;i++){const a=s.hull[i],b=s.hull[(i+1)%s.hull.length],dx=b.x-a.x,dz=b.z-a.z,out=V([dz,0,-dx]).normalize().dot(direction);if(out>best){best=out;edge=[a,b];}}}const origin=edge[0].clone();origin.y=0;let axis=edge[1].clone().sub(edge[0]);axis.y=0;if(axis.lengthSq()<1e-8){const r=direction||body.center.clone().sub(origin);axis=V([r.z,0,-r.x]);}axis.normalize();if(axis.lengthSq()<1e-8)axis=V([0,0,1]);const inertia=body.particles.reduce((sum,p)=>{const r=p.pos.clone().sub(origin);r.addScaledVector(axis,-r.dot(axis));return sum+p.m*r.lengthSq()+p.own;},0);body.pivot={origin,axis,inertia};return s;}
function rotateState(model,body,angle){const {origin,axis}=body.pivot,q=Q().setFromAxisAngle(axis,angle);transformParts(model,body.ids,origin.toArray(),axis.toArray(),angle*180/Math.PI);const turn=p=>p.sub(origin).applyQuaternion(q).add(origin);body.points.forEach(turn);turn(body.center);body.particles.forEach(p=>turn(p.pos));body.angleTravel+=Math.abs(angle);}
export function pushTopple(body,direction=[1,0,0],impulse=.03){if(!Number.isFinite(impulse)||impulse<0||impulse>.5)throw Error('Push impulse must be between 0 and 0.5 N·s.');const dir=V(direction);dir.y=0;if(!dir.lengthSq())return;dir.normalize();choosePivot(body,dir);const {origin,axis,inertia}=body.pivot;body.omega+=body.center.clone().sub(origin).cross(dir.multiplyScalar(impulse*1e6)).dot(axis)/inertia;body.phase='rocking';}
export function stepTopple(model,body,dt){if(!Number.isFinite(dt)||dt<0)throw Error('Invalid stability timestep.');assertUngrounded(model,body.ids);body.accumulator+=Math.min(dt,.1);let changed=false;
 while(body.accumulator+1e-12>=H){body.accumulator-=H;body.elapsed+=H;if(!body.pivot){const s=supportAnalysis(body.points,body.center);if(s.stable||Math.abs(s.margin)<.02){body.phase='resting';continue;}choosePivot(body);body.phase='tipping';}
  const {origin,axis,inertia}=body.pivot,r=body.center.clone().sub(origin),torque=r.cross(V([0,-G*body.mass,0])).dot(axis);body.omega+=torque/inertia*H;body.omega*=Math.exp(-.08*H);let angle=body.omega*H;if(Math.abs(angle)<1e-10)continue;
  const minAfter=t=>{const q=Q().setFromAxisAngle(axis,angle*t);let min=Infinity;for(const p of body.points)min=Math.min(min,p.clone().sub(origin).applyQuaternion(q).add(origin).y);return min;};
  if(minAfter(1)<-.002){let lo=0,hi=1;for(let n=0;n<20;n++){const mid=(lo+hi)/2;if(minAfter(mid)>=-.00001)lo=mid;else hi=mid;}angle*=lo;rotateState(model,body,angle);body.omega=0;body.pivot=null;body.impacts++;body.phase='contact';}
  else rotateState(model,body,angle);changed=true;
 }return changed;
}
